//! Golden-driven tests for `core::transcript` — `validate` accept/reject
//! cases and `export` txt/srt/vtt/json bodies, generated by
//! `tools/oracle/gen_transcript.py` against the v0.6.6 worktree.

use std::path::Path;

use serde_json::{Value, json};
use speakerdesk_core::error::ErrorKind;
use speakerdesk_core::model::Document;
use speakerdesk_core::transcript::{ExportTooLarge, export, validate};

fn goldens(dir: &str) -> Vec<(String, Value)> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/goldens")
        .join(dir);
    let mut cases: Vec<(String, Value)> = std::fs::read_dir(&root)
        .unwrap_or_else(|e| panic!("{root:?}: {e}"))
        .map(|entry| {
            let path = entry.unwrap().path();
            let name = path.file_stem().unwrap().to_str().unwrap().to_string();
            let text = std::fs::read_to_string(&path).unwrap();
            (name, serde_json::from_str(&text).unwrap())
        })
        .collect();
    cases.sort_by(|a, b| a.0.cmp(&b.0));
    cases
}

/// `oracle_lib.expand` — materialize `$repeat_segments`, `$repeat_text` and
/// `$float` recipes.
fn expand(spec: &Value) -> Value {
    match spec {
        Value::Object(map) => {
            if let Some(entry) = map.get("$repeat_segments") {
                let count = entry.get("count").and_then(Value::as_u64).unwrap_or(0) as usize;
                let segment = expand(&entry["segment"]);
                return Value::Array((0..count).map(|_| segment.clone()).collect());
            }
            if let Some(entry) = map.get("$repeat_text") {
                let text = entry.get("text").and_then(Value::as_str).unwrap_or("");
                let count = entry.get("count").and_then(Value::as_u64).unwrap_or(0) as usize;
                return json!(text.repeat(count));
            }
            if let Some(entry) = map.get("$float") {
                // serde_json cannot hold inf/NaN; a string parses to the same
                // non-finite float via the validate() coercion, hitting the
                // same code path.
                let text = entry.as_str().unwrap_or("0");
                let parsed = text.parse::<f64>().unwrap_or(f64::NAN);
                return if parsed.is_finite() {
                    json!(parsed)
                } else {
                    json!(text)
                };
            }
            Value::Object(map.iter().map(|(k, v)| (k.clone(), expand(v))).collect())
        }
        Value::Array(list) => Value::Array(list.iter().map(expand).collect()),
        other => other.clone(),
    }
}

#[test]
fn validate_goldens() {
    for (name, case) in goldens("transcript") {
        if !name.starts_with("validate-") {
            continue;
        }
        let input = &case["input"];
        let document = expand(&input["document"]);
        let duration = input["duration"].as_f64().unwrap();
        let output = &case["output"];
        match validate(&document, duration) {
            Ok(value) => {
                assert_eq!(
                    serde_json::to_value(&value).unwrap(),
                    output["value"],
                    "{name}: expected normalized document",
                );
            }
            Err(e) => {
                assert_eq!(output["error"], json!("ValueError"), "{name}");
                assert_eq!(
                    output["message"],
                    json!(e.message),
                    "{name}: message mismatch (kind={:?})",
                    e.kind
                );
                assert_eq!(e.kind, ErrorKind::BadRequest, "{name}");
            }
        }
    }
}

#[test]
fn export_goldens() {
    for (name, case) in goldens("transcript") {
        if !name.starts_with("export-") {
            continue;
        }
        let input = &case["input"];
        // Export takes the typed `Document`; the golden input is the stored
        // document JSON.
        let document: speakerdesk_core::model::Document =
            serde_json::from_value(expand(&input["document"]))
                .unwrap_or_else(|e| panic!("{name}: document does not fit the model: {e}"));
        let kind = input["kind"].as_str().unwrap();
        let output = &case["output"];
        match export(&document, kind) {
            Ok((content, mimetype)) => {
                assert_eq!(output["mimetype"], json!(mimetype), "{name}");
                let expected = output["content"].as_str().unwrap();
                if kind == "json" {
                    // Python `json.dumps(document)` emits the stored doc
                    // verbatim; our stored doc IS the typed `Document`, so
                    // project the golden through the same boundary — keys
                    // outside the product model (drop-class receipts like
                    // `reading_turn_provenance`, export-local markers) are
                    // gone by design.
                    let ours: Value = serde_json::from_str(&content).unwrap();
                    let theirs: Document = serde_json::from_str(expected).unwrap_or_else(|e| {
                        panic!("{name}: golden doc does not fit the model: {e}")
                    });
                    assert_eq!(
                        ours,
                        serde_json::to_value(&theirs).unwrap(),
                        "{name}: json export document"
                    );
                } else {
                    assert_eq!(content, expected, "{name}: byte-exact export");
                }
            }
            Err(ExportTooLarge) => {
                assert_eq!(output["error"], json!("ExportTooLarge"), "{name}");
                assert_eq!(
                    output["message"],
                    json!(ExportTooLarge.to_string()),
                    "{name}"
                );
            }
        }
    }
}
